def _compute_persistence_score_shadow(
    positive_fold_ratio: float | None,
    fold_sign_ratio: float | None,
) -> float | None:
    """PR2: Stage B 持続性予測 shadow score (audit only、 selection 影響なし).

    archive 実測 Spearman で Stage C 持続性を正予測する 2 metric の加重合成:
    - ``positive_fold_ratio_effective`` (Spearman ρ=+0.345) を 0.7 重み
    - ``fold_sign_ratio`` (Spearman ρ=+0.248) を 0.3 重み

    両 None なら None、 片方 None なら他方のみで計算 (= NaN handling).
    結果は ``[0.0, 1.0]`` にクリップ.

    詳細: devnotes/20260513-1223-todo-pr2-persistence-score-shadow/
    """
    if positive_fold_ratio is None and fold_sign_ratio is None:
        return None
    if positive_fold_ratio is None:
        return max(0.0, min(1.0, float(fold_sign_ratio)))
    if fold_sign_ratio is None:
        return max(0.0, min(1.0, float(positive_fold_ratio)))
    composite = 0.7 * float(positive_fold_ratio) + 0.3 * float(fold_sign_ratio)
    return max(0.0, min(1.0, composite))


def _finite_or_none(value: object) -> float | None:
    """PR3: Parquet float64 互換のため ``±inf`` / NaN / None / 非数値 を None に正規化.

    archive 列が ``pa.float64()`` nullable で、 ``±inf`` は技術的には書き込めるが
    downstream 解析の単純化のため有限値 / None のみに統一する。 boolean は
    ``isinstance(True, int) == True`` で float() 変換が成立するが、 PR3 shadow
    列は float 専用のため明示的に弾く (= caller が gate_pass を誤って渡した時の
    defensive).

    Args:
        value: 数値 / None / NaN / ±inf 想定。 boolean / 文字列等は ``None`` 扱い.

    Returns:
        有限 float なら ``float(value)``、 ``None`` / NaN / ``±inf`` / 非数値型
        なら ``None``.
    """
    if value is None:
        return None
    if isinstance(value, bool):
        return None
    try:
        f = float(value)  # type: ignore[arg-type]
    except (TypeError, ValueError):
        return None
    if not math.isfinite(f):
        return None
    return f


def _extract_canonical_shadow(
    payload: Mapping[str, object],
    key: str,
) -> tuple[bool | None, float | None, float | None]:
    """PR3: stage_gate payload から canonical_shadow summary を抽出.

    Args:
        payload: ``stage_result.metrics["payload"]``.
        key: ``"canonical_shadow_b_is"`` (Stage B) /
            ``"canonical_shadow_c_base"`` (Stage C).

    Returns:
        ``(gate_pass, mission_inf_gap, mission_signed_margin)`` tuple。
        payload に key が無い / 値が None / 非 Mapping / field 欠損のとき、
        該当値は ``None`` で返す (= defensive、 stage_gate が PR3 未対応バージョン
        の場合でも archive 側で安全に fall through する).

    詳細: ``devnotes/20260513-1419-todo-pr3-canonical-mission-shadow/``.
    """
    shadow = payload.get(key)
    if not isinstance(shadow, Mapping):
        return (None, None, None)
    gate_pass_raw = shadow.get("gate_pass")
    gate_pass: bool | None = (
        gate_pass_raw if isinstance(gate_pass_raw, bool) else None
    )
    return (
        gate_pass,
        _finite_or_none(shadow.get("mission_inf_gap")),
        _finite_or_none(shadow.get("mission_signed_margin")),
    )


def _extract_pareto_b_shadow(
    payload: Mapping[str, object],
) -> tuple[float | None, float | None, float | None, bool | None]:
    """T112: payload の ``pareto_features_lite_b`` (ParetoFeaturesLite) を defensive 抽出.

    ``stage_gate.evaluate_stage_b`` が payload に格納した ParetoFeaturesLite から
    selection 用 3 軸 + usable flag を取り出す。duck-typing で読み (import 不要)、
    欠損 / 型不正 / 非有限は None に潰す (= 旧 stage_gate / unusable でも安全)。

    Returns:
        ``(net_pnl, pooled_dd, mission_inf_gap, axis_usable)``。
    """
    lite = payload.get("pareto_features_lite_b")
    if lite is None:
        return (None, None, None, None)
    usable_raw = getattr(lite, "pareto_axis_usable", None)
    usable: bool | None = usable_raw if isinstance(usable_raw, bool) else None
    return (
        _finite_or_none(getattr(lite, "net_pnl_after_cost", None)),
        _finite_or_none(getattr(lite, "pooled_dd_per_fold_max", None)),
        _finite_or_none(getattr(lite, "mission_inf_gap", None)),
        usable,
    )


